import React, { useEffect, useState } from "react";
import axios from "axios";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { Line, Pie } from "react-chartjs-2";
import {
  format,
  parseISO,
  subDays,
  formatISO,
  startOfDay,
  endOfDay,
} from "date-fns";
import "chart.js/auto";
import "./Dashboard.css";

function Dashboard() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [visibleCount, setVisibleCount] = useState(10);
  const [visibleItemAndComboCount, setVisibleItemAndComboCount] = useState(10);
  const [grouping, setGrouping] = useState("1h");
  const [activeChart, setActiveChart] = useState("amount");
  const [startDate, setStartDate] = useState(formatISO(subDays(new Date(), 7)));
  const [endDate, setEndDate] = useState(formatISO(new Date()));

  const chartColors = [
    "#a29bfe",
    "#6c5ce7",
    "#74b9ff",
    "#00b894",
    "#55efc4",
    "#ffeaa7",
    "#fab1a0",
    "#fd79a8",
    "#e17055",
    "#636e72",
  ];

  const commonLineStyle = {
    borderColor: "#9b59b6",
    backgroundColor: "#9b59b622",
    fill: true,
    tension: 0.3,
    pointRadius: 4,
    pointHoverRadius: 6,
  };

  useEffect(() => {
    axios
      .get("http://localhost:8080/api/summary")
      .then((res) => {
        console.log("API Response:", res.data);
        setSummary(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching summary:", err);
        setLoading(false);
      });
  }, []);

  const fetchFilteredData = () => {
    setLoading(true);
    axios
      .get("http://localhost:8080/api/summary", {
        params: { start: startDate, end: endDate },
      })
      .then((res) => {
        setSummary(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching filtered summary:", err);
        setLoading(false);
      });
  };

  const totalSales = summary?.totalSales ?? 0;
  const numTransactions = summary?.numTransactions ?? 0;
  const avgTransactionValue = summary?.avgTransactionValue ?? 0;
  const mostSoldProducts = summary?.mostSoldProducts ?? [];
  const leastSoldProducts = summary?.leastSoldProducts ?? [];
  const soldCombos = summary?.soldCombos ?? {};
  const mostSoldCombos = summary?.mostSoldCombos ?? {};
  const leastSoldCombos = summary?.leastSoldCombos ?? {};
  const transactions = summary?.transactions ?? [];
  const salesOverTime = summary?.salesOverTime ?? [];

  const groupedData = groupSales(salesOverTime, grouping);
  const groupedSalesCount = groupSalesCount(salesOverTime, grouping);

  if (loading) return <p className="loading">Loading dashboard...</p>;

  return (
    <div className="dashboard-container">
      <h1 className="dashboard-title">SumUp Dashboard</h1>

      <div className="summary-cards">
        <div>
          <strong>Total Sales:</strong> €{totalSales}
        </div>
        <div>
          <strong>Transactions:</strong> {numTransactions}
        </div>
        <div>
          <strong>Average:</strong> €{avgTransactionValue}
        </div>
      </div>

      <div className="date-filter">
        <div className="date-picker-group">
          <label htmlFor="from-date">From:</label>
          <DatePicker
            id="from-date"
            selected={new Date(startDate)}
            onChange={(date) => setStartDate(formatISO(startOfDay(date)))}
            dateFormat="dd-MM-yyyy"
            className="custom-datepicker"
          />
        </div>
        <div className="date-picker-group">
          <label htmlFor="to-date">To:</label>
          <DatePicker
            id="to-date"
            selected={new Date(endDate)}
            onChange={(date) => setEndDate(formatISO(endOfDay(date)))}
            dateFormat="dd-MM-yyyy"
            className="custom-datepicker"
          />
        </div>
        <button onClick={fetchFilteredData} className="filter-button">
          Apply Filter
        </button>
      </div>

      <div className="chart-section">
        <div className="grouping-buttons">
          <button
            onClick={() => {
              if (grouping === "weekday+time") setGrouping("1d");
              setActiveChart("amount");
            }}
            className={activeChart === "amount" ? "active" : ""}
          >
            Show Sales Amount
          </button>
          <button
            onClick={() => setActiveChart("count")}
            className={activeChart === "count" ? "active" : ""}
          >
            Show Sales Count
          </button>
        </div>
        <h2>
          {activeChart === "amount"
            ? "Sales Over Time"
            : "Number of Sales Per Period"}
        </h2>
        <div className="grouping-buttons">
          <button
            onClick={() => setGrouping("30m")}
            className={grouping === "30m" ? "active" : ""}
          >
            30 min
          </button>
          <button
            onClick={() => setGrouping("1h")}
            className={grouping === "1h" ? "active" : ""}
          >
            1 hour
          </button>
          <button
            onClick={() => setGrouping("1d")}
            className={grouping === "1d" ? "active" : ""}
          >
            1 day
          </button>
          {activeChart === "count" && (
            <button
              onClick={() => setGrouping("weekday+time")}
              className={grouping === "weekday+time" ? "active" : ""}
            >
              Weekday + Time
            </button>
          )}
        </div>
        <Line
          data={{
            labels: (activeChart === "amount"
              ? groupedData
              : groupedSalesCount
            ).map((pt) => pt.date),
            datasets: [
              {
                label:
                  activeChart === "amount" ? "Sales (€)" : "Number of Sales",
                data: (activeChart === "amount"
                  ? groupedData
                  : groupedSalesCount
                ).map((pt) =>
                  activeChart === "amount" ? pt.amount : pt.count
                ),
                ...commonLineStyle,
              },
            ],
          }}
          options={{
            responsive: true,
            plugins: { legend: { labels: { color: "#f5f6fa" } } },
            scales: {
              x: { ticks: { color: "#aaa" }, grid: { color: "#333" } },
              y: { ticks: { color: "#aaa" }, grid: { color: "#333" } },
            },
          }}
        />
      </div>

      <div className="charts-grid">
        {[
          ["Most Sold Items", mostSoldProducts],
          ["Least Sold Items", leastSoldProducts],
        ].map(([title, list], i) => (
          <div key={i} className="chart-block">
            <h2>{title}</h2>
            <Pie
              data={{
                labels: list.map((p) => p.name),
                datasets: [
                  {
                    data: list.map((p) => p.quantity),
                    backgroundColor: chartColors,
                    borderWidth: 1,
                  },
                ],
              }}
              options={{
                cutout: "60%",
                plugins: { legend: { labels: { color: "#fff" } } },
              }}
            />
          </div>
        ))}

        {[
          ["Most Sold Combos", mostSoldCombos],
          ["Least Sold Combos", leastSoldCombos],
        ].map(([title, obj], i) => (
          <div key={title} className="chart-block">
            <h2>{title}</h2>
            <Pie
              data={{
                labels: Object.keys(obj),
                datasets: [
                  {
                    data: Object.values(obj),
                    backgroundColor: chartColors,
                    borderWidth: 1,
                  },
                ],
              }}
              options={{
                cutout: "60%",
                plugins: { legend: { labels: { color: "#fff" } } },
              }}
            />
          </div>
        ))}
      </div>

      <div className="dual-table-wrapper">
        <div className="table-block">
          <h2>Most Sold Items</h2>
          <table className="data-table">
            <thead>
              <tr>
                <th>Item</th>
                <th>Quantity</th>
              </tr>
            </thead>
            <tbody>
              {mostSoldProducts.length === 0 ? (
                <tr>
                  <td colSpan="2">No data</td>
                </tr>
              ) : (
                mostSoldProducts
                  .slice(0, visibleItemAndComboCount)
                  .map((item, i) => (
                    <tr key={i}>
                      <td>{item.name}</td>
                      <td>{item.quantity}</td>
                    </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>

        <div className="table-block">
          <h2>Most Sold Combos</h2>
          <table className="data-table">
            <thead>
              <tr>
                <th>Combo</th>
                <th>Count</th>
              </tr>
            </thead>
            <tbody>
              {Object.keys(soldCombos).length === 0 ? (
                <tr>
                  <td colSpan="2">No data</td>
                </tr>
              ) : (
                Object.entries(soldCombos)
                  .slice(0, visibleItemAndComboCount)
                  .map(([combo, count], i) => (
                    <tr key={i}>
                      <td>{combo}</td>
                      <td>{count}</td>
                    </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {(visibleItemAndComboCount < mostSoldProducts.length ||
        visibleItemAndComboCount < Object.keys(soldCombos).length) && (
        <div className="load-more-container">
          <button
            onClick={() => setVisibleItemAndComboCount((c) => c + 10)}
            className="load-more-button"
          >
            Load More
          </button>
        </div>
      )}

      <div className="transactions-section">
        <h2>Recent Transactions</h2>
        <table className="transactions-table">
          <thead>
            <tr>
              <th>Date</th>
              <th>Amount (€)</th>
              <th>Payment Type</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {transactions.length === 0 ? (
              <tr>
                <td colSpan="4">No transactions</td>
              </tr>
            ) : (
              transactions.slice(0, visibleCount).map((tx) => (
                <tr key={tx.id}>
                  <td>{tx.date}</td>
                  <td>{tx.amount}</td>
                  <td>{tx.paymentType}</td>
                  <td>{tx.status}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {visibleCount < transactions.length && (
        <div className="load-more-container">
          <button
            onClick={() => setVisibleCount((c) => c + 10)}
            className="load-more-button"
          >
            Load More
          </button>
        </div>
      )}
    </div>
  );
}

function groupSales(sales, interval) {
  const buckets = {};
  const uniqueDates = Array.from(
    new Set(sales.map((pt) => format(parseISO(pt.date), "dd-MM-yyyy")))
  );
  uniqueDates.forEach((dateStr) => {
    for (let h = 6; h < 21; h++) {
      const hour = h.toString().padStart(2, "0");
      if (interval === "30m") {
        buckets[`${dateStr} ${hour}:00`] = 0;
        buckets[`${dateStr} ${hour}:30`] = 0;
      } else if (interval === "1h") {
        buckets[`${dateStr} ${hour}:00`] = 0;
      }
    }
    if (interval === "1d") buckets[dateStr] = 0;
  });
  sales.forEach((pt) => {
    const date = parseISO(pt.date);
    let key;
    if (interval === "30m") {
      key = `${format(date, "dd-MM-yyyy")} ${date
        .getHours()
        .toString()
        .padStart(2, "0")}:${date.getMinutes() < 30 ? "00" : "30"}`;
    } else if (interval === "1h") {
      key = `${format(date, "dd-MM-yyyy")} ${date
        .getHours()
        .toString()
        .padStart(2, "0")}:00`;
    } else {
      key = format(date, "dd-MM-yyyy");
    }
    buckets[key] = (buckets[key] ?? 0) + pt.amount;
  });
  return Object.entries(buckets)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, amount]) => ({ date, amount }));
}

function groupSalesCount(sales, interval) {
  const buckets = {};
  const weekdays = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];
  if (interval === "1d") weekdays.forEach((day) => (buckets[day] = 0));
  if (["1h", "30m"].includes(interval)) {
    for (let h = 6; h < 21; h++) {
      const hour = h.toString().padStart(2, "0");
      if (interval === "1h") buckets[`${hour}:00`] = 0;
      else {
        buckets[`${hour}:00`] = 0;
        buckets[`${hour}:30`] = 0;
      }
    }
  }
  if (interval === "weekday+time") {
    weekdays.forEach((day) => {
      for (let h = 6; h < 21; h++) {
        const hour = h.toString().padStart(2, "0");
        buckets[`${day} ${hour}:00`] = 0;
        buckets[`${day} ${hour}:30`] = 0;
      }
    });
  }
  sales.forEach((pt) => {
    const date = parseISO(pt.date);
    const day = format(date, "EEEE");
    const hour = date.getHours().toString().padStart(2, "0");
    const half = date.getMinutes() < 30 ? "00" : "30";
    let key =
      interval === "1d"
        ? day
        : interval === "1h"
        ? `${hour}:00`
        : interval === "30m"
        ? `${hour}:${half}`
        : `${day} ${hour}:${half}`;
    buckets[key] = (buckets[key] ?? 0) + 1;
  });
  const sorted = interval === "1d" ? weekdays : Object.keys(buckets).sort();
  return sorted.map((date) => ({ date, count: buckets[date] }));
}

export default Dashboard;
